# doc: expect 19
func main() -> int:
    mut words = ["alpha", "beta"]
    mut letters = 0
    for word in words:
        for letter in word:
            letters += 1
    mut weighted = 0
    for index, word in enumerate(words):
        weighted += index * len(word)
    mut octets = 0
    for octet in b"\x01\x02":
        octets += octet
    mut counts: dict[str, int] = {"a": 1, "b": 2}
    mut keyed = ""
    for key in counts:
        keyed = keyed + key
    if keyed != "ab":
        return 1
    mut stepped = 0
    for number in range(1, 5):
        if number == 3:
            continue
        if number == 4:
            break
        stepped += number
    return letters + weighted + octets + stepped

