func main() -> int:
    mut left: int[] = [1, 2, 3]
    mut right: int[] = [1, 2, 3]
    if left != right:
        return 1
    if 2 not in left:
        return 2
    if 9 in left:
        return 3
    mut nested: int[][] = [left]
    mut twin: int[][] = [right]
    if nested != twin:
        return 4
    mut counts: dict[str, int] = {"a": 1, "b": 2}
    mut other: dict[str, int] = {"b": 2, "a": 1}
    if counts != other:
        return 5
    if "a" not in counts:
        return 6
    if "ell" not in "hello":
        return 7
    if "zz" in "hello":
        return 8
    return len(left) * 14

